        )
        log.info(
            "advance_quest ok project=%s type=%s number=%s status=%s",
            data["project"],
            data["quest_type"],
            data["quest_number"],
            result.get("status"),
        )
        return jsonify(result), 200

    @app.route("/land", methods=["POST"])
    def land_route():
        data = request.get_json(force=True)
