                quest_dir=qdir,
                agent_key=agent_key,
                step=step,
            )
        except (DashboardBadRequest, DashboardNotFound) as exc:
            ws.send(json.dumps({"type": "error", "message": str(exc)}))
            return
        except Exception:
            log.exception("agent_log stream setup failed")
            ws.send(json.dumps({"type": "error", "message": "Internal server error"}))
