            import threading

            def _exit_process() -> None:
                os._exit(0)

            timer = threading.Timer(0.1, _exit_process)
            timer.daemon = True
            timer.start()
        return jsonify({"status": "exiting"}), 200

    @app.route("/experiments/create", methods=["POST"])
